import json, subprocess, itertools, numpy as np
rng=np.random.default_rng(76439);cases=[]
def add(op,rows,args,oracle):
 text=op+'|'+','.join(map(str,args))+'|'+';'.join(','.join(map(str,r)) for r in rows)
 cases.append((text,op,oracle))
for _ in range(200):
 p=int(rng.integers(1,9));n=int(rng.integers(p+3,p+40));D=rng.normal(0,1,(n,p))*rng.uniform(.3,3,p)+rng.uniform(-5,5,p);X=np.c_[np.ones(n),D];G=X.T@X;I=np.linalg.inv(G);Z=np.c_[np.ones(n),(D-D.mean(0))/np.sqrt(np.mean((D-D.mean(0))**2,axis=0))]
 add('design_evaluate',D,[],{'numeric':{'information_matrix':G,'inverse_information_matrix':I,'log_determinant':np.linalg.slogdet(G)[1],'coded_log_determinant':np.linalg.slogdet(Z.T@Z)[1],'condition_number_coded':np.linalg.cond(Z),'leverages':np.einsum('ij,jk,ik->i',X,I,X)}})
for p in range(1,65):
 add('orthogonal_screening',[[-1,1]]*p,[],{'orthogonal':p})
for base in range(2,8):
 p=min(64,2**base-1);masks=[m for m in range(1,2**base) if m.bit_count()>=2][:p-base]
 add('fractional_factorial',[[-1,1]]*p,[base,0,*masks],{'orthogonal':p})
for p in range(3,9):
 add('box_behnken',[[-1,1]]*p,[1],{'box':p})
for _ in range(40):
 p=int(rng.integers(1,9));n=int(rng.integers(2,80));lo=rng.uniform(-20,20,p);hi=lo+rng.uniform(.5,5,p)
 add('latin_hypercube',list(zip(lo,hi)),[n,int(rng.integers(0,1000000))],{'lhs':(p,n,lo,hi)})
for _ in range(60):
 p=int(rng.integers(2,5));degree=int(rng.integers(1,6));unit=10.**rng.uniform(-40,40);lo=rng.uniform(0,.07,p);hi=rng.uniform(.5,.95,p);remaining=1-lo.sum()
 points=[]
 for counts in itertools.product(range(degree+1),repeat=p):
  if sum(counts)!=degree:continue
  point=lo+remaining*np.array(counts)/degree
  if np.all(point<=hi+1e-13):points.append(point)
 add('mixture_lattice',list(zip(lo*unit,hi*unit)),[degree,unit],{'mixture':(np.array(points),unit)})
for _ in range(30):
 n=int(rng.choice([6,8,12,16,18,24]));r=int(rng.integers(1,5));blocks=int(rng.choice([b for b in range(1,n+1) if n%b==0]))
 add('randomize_design',[[i,i+100]for i in range(n)],[r,int(rng.integers(0,1000000)),blocks],{'random':(n,r,blocks)})
proc=subprocess.run(['/private/tmp/rusta-ducksmiles-jmp-target/inference-check/design_runner'],input='\n'.join(c[0]for c in cases)+'\n',text=True,capture_output=True,check=True)
errors=[];maxerror=(0,None)
for (_,op,oracle),out in zip(cases,proc.stdout.splitlines()):
 if out.startswith('ERROR'):
  if 'mixture'in oracle and len(oracle['mixture'][0])==0:continue
  errors.append((op,out));continue
 result=json.loads(out)
 if 'numeric'in oracle:
  for key,expected in oracle['numeric'].items():
   aa=np.asarray(result[key]);ee=np.asarray(expected);error=float(np.max(np.abs(aa-ee)/np.maximum(1,np.abs(ee))))
   if error>maxerror[0]:maxerror=(error,key)
   if error>2e-8:errors.append((op,key,error))
 if 'orthogonal'in oracle:
  p=oracle['orthogonal'];a=np.asarray(result['coded_rows']);X=np.c_[np.ones(len(a)),a]
  if not np.array_equal(X.T@X,np.eye(p+1)*len(a)):errors.append((op,'not orthogonal'))
 if 'box'in oracle:
  p=oracle['box'];a=np.asarray(result['coded_rows']);X=np.c_[np.ones(len(a)),a,a*a,np.array([a[:,i]*a[:,j]for i in range(p)for j in range(i+1,p)]).T]
  if len(a)!=2*p*(p-1)+1 or np.linalg.matrix_rank(X)!=X.shape[1]:errors.append((op,'run count or quadratic rank'))
 if 'lhs'in oracle:
  p,n,lo,hi=oracle['lhs'];a=np.asarray(result['rows']);strata=np.floor((a-lo)/(hi-lo)*n).astype(int)
  if any(not np.array_equal(np.sort(strata[:,j]),np.arange(n))for j in range(p)):errors.append((op,'strata'))
 if 'mixture'in oracle:
  expected,unit=oracle['mixture'];actual=np.asarray(result['rows'])/unit
  if actual.shape!=expected.shape or np.max(abs(actual-expected))>1e-12:errors.append((op,'composition discrepancy'))
 if 'random'in oracle:
  n,r,b=oracle['random'];rows=np.asarray(result['rows']);source=np.asarray(result['source_indices']);rep=np.asarray(result['replicate_labels']);blocks=np.asarray(result['block_labels'])
  if any(not np.array_equal(np.sort(source[i*n:(i+1)*n]),np.arange(n))for i in range(r)):errors.append((op,'source loss'))
  if any(np.count_nonzero((rep==i)&(blocks==j))!=n//b for i in range(r)for j in range(b)):errors.append((op,'unbalanced block'))
print(json.dumps({'cases':len(cases),'max_scaled_absolute_error':maxerror,'failure_count':len(errors),'errors':errors[:20]}))
